const accessLabels={admin:'Administrador',finance:'Financeiro',operator:'Operador de impressão'};
const financeCategories={capital:'Aporte / investimento',membership:'Participação no clube',printing:'Impressão',filament:'Compra de filamento',equipment:'Equipamentos',maintenance:'Manutenção',rent:'Aluguel',energy:'Energia',services:'Serviços',sales:'Venda de peças',supplies:'Insumos',shipping:'Entrega / frete',other_income:'Outras receitas',other_expense:'Outras despesas',allowance:'Mesada',gift:'Presente',purchase:'Compras'};
const adminUser=()=>state.user?.role==='admin'||state.user?.team_role==='admin';
const financeUser=()=>adminUser()||(Boolean(state.user?.is_staff)&&state.user?.team_role==='finance');
const operatorUser=()=>adminUser()||(Boolean(state.user?.is_staff)&&(!state.user?.team_role||state.user.team_role==='operator'));
function todayLocal(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-');}
// Datas digitadas em dd/mm/aaaa (o seletor do navegador segue o idioma do computador e confunde).
const dateBr=iso=>iso.split('-').reverse().join('/');
function dateIso(text){const m=/^(\d{2})\/(\d{2})\/(\d{4})$/.exec(String(text).trim());const iso=m&&`${m[3]}-${m[2]}-${m[1]}`;if(!iso||Number.isNaN(Date.parse(iso))||new Date(iso+'T00:00:00Z').toISOString().slice(0,10)!==iso)throw new Error('Use a data no formato dd/mm/aaaa, por exemplo 30/11/2026.');if(iso<todayLocal())throw new Error('A validade não pode estar no passado.');return iso;}
const dateField=(label,name,iso)=>`<label>${label}<input name="${name}" class="date-br" inputmode="numeric" maxlength="10" placeholder="dd/mm/aaaa" pattern="\\d{2}/\\d{2}/\\d{4}" autocomplete="off" required value="${dateBr(iso)}"></label>`;
function defaultExpiry(){const d=todayLocal(),[y,m]=d.split('-').map(Number);return d.slice(0,7)+'-'+new Date(Date.UTC(y,m,0)).getUTCDate();}
function roleOptions(selected='operator'){return Object.entries(accessLabels).map(([v,label])=>`<option value="${v}" ${v===selected?'selected':''}>${label}</option>`).join('');}
async function loadOperationsPage(){
 if(['finance-club','finance-family'].includes(state.page)||(state.page==='home'&&financeUser()&&!operatorUser())){
  const scope=state.page==='finance-family'?'family':'club',range=state.financeRange?.[scope]||{};
  state.finance=await api('/finance?'+new URLSearchParams({scope,...range}));
 }
 if(state.page==='stock')state.stock=await api('/stock');
 if(state.page==='finance-dashboard')await loadFinanceDashboard();
}
function contactsHtml(members){return members.map(m=>`<div class="person-row"><div><strong>${esc(m.name)}</strong><small>${['guardian','admin'].includes(m.role)?'Responsável':'Aprendiz'}${m.is_staff?' · Equipe':''}</small>${m.email.endsWith('@maker3d.invalid')?'<small>Acesso pela conta do responsável</small>':`<a href="mailto:${esc(m.email)}">${esc(m.email)}</a>`}${['guardian','admin'].includes(m.role)?m.whatsapp?`<p class="contact-phone">${esc(m.whatsapp)} <a class="text-btn" href="https://wa.me/${encodeURIComponent(m.whatsapp)}" target="_blank" rel="noopener noreferrer">Abrir WhatsApp ↗</a></p>`:'<small>WhatsApp ainda não informado no perfil.</small>':''}</div>${adminUser()?btn('Editar','member-edit','secondary small',`data-id="${m.id}"`):''}</div>`).join('')||'<p>Nenhum acesso cadastrado. Gere um convite para o responsável.</p>';}
// Team view lists every family, so each card shows only the quota bar; the full breakdown stays in the family's own view.
function familyQuota(b){if(!b)return '';const percent=b.allowance?Math.round(b.available/b.allowance*100):0,red=b.extraMinutes>0,low=!red&&percent<=20;return `<div class="family-quota ${red?'red':low?'amber':''}"><div class="row spread"><strong>${hours(b.available)}</strong><small>de ${hours(b.allowance)} · ${percent}% livre</small></div><progress max="${b.allowance||1}" value="${b.available}" aria-label="Horas disponíveis da franquia"></progress><small>Reservadas ${hours(b.held)} · Adicionais ${money(b.total)}${red?` · ${hours(b.extraMinutes)} extras`:''}</small></div>`;}
function operationsFamilies(){const fs=teamUser()?state.data.families:[{...state.data.family,participants:state.data.participants,members:state.data.familyMembers||[],balance:state.data.balance}];return `${header('PESSOAS QUE CRIAM JUNTAS',teamUser()?'Famílias do clube':'Minha família','Contatos, participantes, horas e benefícios.',operatorUser()?btn('Nova família','family-new')+btn('Dar horas a várias famílias','hours-bulk','secondary'):'')}<div class="family-grid ${teamUser()?'compact':''}">${fs.map(f=>`<article class="card family-card"><div class="row spread"><h2>${esc(f.name)}</h2>${operatorUser()||state.user.family_id===f.id?btn('Editar família','family-edit','secondary small',`data-id="${f.id}"`):''}</div><p>${f.plan==='annual'?'Plano anual':'Plano mensal'} · ${hours(f.allowance)} de franquia por mês</p>${teamUser()?familyQuota(f.balance):batteryHtml(f.balance,true)}${f.balance.giftAvailable?`<p>Inclui ${hours(f.balance.giftAvailable)} de bônus disponíveis. Cada concessão tem sua própria validade.</p>`:''}<div class="section"><h3>Contatos e acessos</h3>${contactsHtml(f.members)}</div><div class="section-head section"><h3>Dependentes e participantes</h3>${operatorUser()||state.user.family_id===f.id?btn('Adicionar','dependent-new','secondary small',`data-family="${f.id}"`):''}</div>${f.participants.map(p=>`<div class="person-row"><div><strong>${esc(p.name)}</strong><small>${ageLabels[p.age_group]}${p.active?'':' · Inativo'}</small></div><div class="row">${!teamUser()&&guardianUser()&&p.active?btn('Entrar como '+esc(p.name),'family-enter','small',`data-participant="${p.id}"`):''}${operatorUser()||state.user.family_id===f.id?btn('Editar','dependent-edit','secondary small',`data-id="${p.id}" data-family="${f.id}"`):''}</div></div>`).join('')||'<p>Nenhum participante cadastrado.</p>'}<div class="row section">${operatorUser()?btn('Gerar convite','invite-dialog','secondary small',`data-id="${f.id}"`):''}${financeUser()?btn('Dar cupom ou horas','benefit-dialog','secondary small',`data-id="${f.id}"`)+btn('Registrar pagamento','payment-dialog','secondary small',`data-id="${f.id}"`):''}${btn('Histórico de benefícios','benefits-history','secondary small',`data-id="${f.id}"`)}</div></article>`).join('')}</div>`;}
function operationsTeam(){return `${header('QUEM FAZ O CLUBE ACONTECER','Equipe e acessos','Escolha uma função ou convide um colaborador sem vínculo com família.',btn('Convidar colaborador','staff-invite'))}<div class="grid three"><div class="card"><h3>Administrador</h3><p>Gerencia equipe, preços, financeiro, famílias e produção.</p></div><div class="card"><h3>Financeiro</h3><p>Registra recebimentos, aportes, despesas e compras, concede benefícios e consulta contatos. Não opera impressões nem concede acessos.</p></div><div class="card"><h3>Operador de impressão</h3><p>Atende famílias, prepara orçamentos, opera a produção e registra baixas de estoque. Não acessa o caixa nem registra recebimentos.</p></div></div><div class="card section"><h2>Equipe atual</h2>${(state.team?.members||[]).map(m=>`<div class="person-row"><div><strong>${esc(m.name)}</strong><small>${esc(m.email)} · ${m.role==='admin'?'Administrador inicial':accessLabels[m.access_role]}</small></div>${m.role!=='admin'&&m.id!==state.user.id?`<div class="row">${btn('Alterar função','team-role','secondary small',`data-id="${m.id}" data-role="${m.access_role}"`)}${btn('Remover da equipe','team-toggle','secondary small',`data-id="${m.id}" data-enabled="false"`)}</div>`:''}</div>`).join('')}</div><div class="card section"><h2>Adicionar um responsável já cadastrado</h2>${state.data.families.flatMap(f=>f.members.filter(m=>m.role==='guardian'&&!m.is_staff).map(m=>`<div class="person-row"><div><strong>${esc(m.name)}</strong><small>${esc(m.email)} · ${esc(f.name)}</small></div>${btn('Adicionar à equipe','team-toggle','secondary small',`data-id="${m.id}" data-enabled="true"`)}</div>`)).join('')||'<p>Nenhum responsável disponível.</p>'}</div><div class="card section"><h2>Convites de colaboradores</h2>${(state.team?.invites||[]).map(i=>`<div class="person-row"><div><strong>${esc(i.email)}</strong><small>${accessLabels[i.access_role]} · ${Number(i.expires)>Date.now()?'Válido até '+date(Number(i.expires)):'Expirado'}</small></div>${btn('Revogar convite','staff-revoke','secondary small',`data-id="${esc(i.token)}"`)}</div>`).join('')||'<p>Nenhum convite pendente.</p>'}</div><details class="card section"><summary>Histórico administrativo</summary>${(state.team?.audit||[]).map(a=>`<p><strong>${esc(a.name)}</strong> · ${esc(a.action)} · ${esc(a.target)}<br><small>${date(a.created)}</small></p>`).join('')}</details>`;}
function financeView(){state.financeView??={};return state.financeView[state.finance.scope]??={search:'',kind:'all',category:'all',participant:'all',status:'active',sort:'date_desc',page:1};}
function financeVisibleEntries(){const v=financeView(),fold=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),q=fold(v.search).trim();
 const rows=state.finance.entries.filter(e=>(v.participant==='all'||e.participant_key===v.participant)&&(v.kind==='all'||e.kind===v.kind)&&(v.category==='all'||e.category===v.category)&&(v.status==='all'||(v.status==='voided'?Boolean(e.voided_at):!e.voided_at))&&(!q||fold([e.description,e.family_name,e.participant_name,financeCategories[e.category],e.entry_date].join(' ')).includes(q)));
 return rows.sort((a,b)=>{switch(v.sort){case'date_asc':return a.entry_date.localeCompare(b.entry_date)||a.id-b.id;case'value_desc':return b.cents-a.cents||b.id-a.id;case'value_asc':return a.cents-b.cents||b.id-a.id;case'description':return a.description.localeCompare(b.description,'pt-BR')||b.id-a.id;default:return b.entry_date.localeCompare(a.entry_date)||b.id-a.id;}});
}
function financeTableHtml(){const f=state.finance,v=financeView(),rows=financeVisibleEntries(),size=20,pages=Math.max(1,Math.ceil(rows.length/size));v.page=Math.min(v.page,pages);
 const visible=rows.slice((v.page-1)*size,v.page*size),live=rows.filter(e=>!e.voided_at),incoming=live.filter(e=>e.kind!=='expense').reduce((n,e)=>n+e.cents,0),outgoing=live.filter(e=>e.kind==='expense').reduce((n,e)=>n+e.cents,0);
 return `<div class="finance-list-meta"><span role="status">${rows.length} de ${f.entries.length} lançamentos no período</span><span>Entradas listadas <b>${money(incoming)}</b><i>·</i> Saídas <b>${money(outgoing)}</b></span></div><div class="table-scroll"><table class="finance-table"><thead><tr><th scope="col">Data</th><th scope="col">Descrição / vínculo</th><th scope="col">Classificação</th>${f.scope==='family'?'<th scope="col">Participante</th>':''}<th scope="col" class="finance-amount">Valor</th><th scope="col">Situação</th><th scope="col" aria-label="Ações"></th></tr></thead><tbody>${visible.map(e=>`<tr class="${e.voided_at?'voided':''}"><td class="finance-date">${esc(e.entry_date.split('-').reverse().join('/'))}</td><td class="finance-description"><strong>${esc(e.description)}</strong>${e.family_name?`<small>${esc(e.family_name)}</small>`:e.scope==='club'&&f.scope==='family'?'<small>Pagamento confirmado pelo clube</small>':''}${e.voided_at?`<small>Estorno: ${esc(e.void_reason)}</small>`:''}</td><td><span class="finance-kind ${e.kind}">${({income:'Receita',expense:'Despesa',investment:'Aporte'})[e.kind]}</span><small>${financeCategories[e.category]||esc(e.category)}</small></td>${f.scope==='family'?`<td>${esc(e.participant_name||'Família')}</td>`:''}<td class="finance-amount ${e.kind==='expense'?'is-outflow':'is-inflow'}">${e.kind==='expense'?'−':'+'}${money(e.cents)}</td><td><span class="finance-status ${e.voided_at?'':'confirmed'}">${e.voided_at?'Estornado':'Confirmado'}</span></td><td>${e.canVoid?btn('Estornar','finance-void','secondary small',`data-id="${e.id}"`):'<span aria-label="Sem ações disponíveis">—</span>'}</td></tr>`).join('')||`<tr><td colspan="${f.scope==='family'?7:6}"><div class="finance-no-results"><strong>Nenhum lançamento encontrado</strong><span>Altere o período ou limpe os filtros para ver outros registros.</span></div></td></tr>`}</tbody></table></div>${pages>1?`<div class="finance-pagination"><span>${(v.page-1)*size+1}–${Math.min(v.page*size,rows.length)} de ${rows.length}</span><div>${btn('Anterior','finance-page','secondary small',`data-page="${v.page-1}" ${v.page===1?'disabled':''}`)}<span>Página ${v.page} de ${pages}</span>${btn('Próxima','finance-page','secondary small',`data-page="${v.page+1}" ${v.page===pages?'disabled':''}`)}</div></div>`:''}`;
}
function updateFinanceList(){const target=$('#finance-list');if(target)target.innerHTML=financeTableHtml();}
function financePage(){const f=state.finance,t=f.totals,club=f.scope==='club',v=financeView(),options=(list,value)=>list.map(([key,label])=>`<option value="${esc(key)}" ${key===value?'selected':''}>${esc(label)}</option>`).join(''),categories=[...new Set([...f.entries.map(e=>e.category),...(v.category!=='all'?[v.category]:[])])].sort((a,b)=>(financeCategories[a]||a).localeCompare(financeCategories[b]||b,'pt-BR'));
 const costs=new Map();for(const e of f.entries)if(!e.voided_at&&e.kind==='expense')costs.set(e.category,(costs.get(e.category)||0)+e.cents);const major=[...costs].sort((a,b)=>b[1]-a[1]).slice(0,3);
 const metric=(label,value,key,extra='',tone='')=>`<div class="finance-metric ${tone}" data-finance-metric="${key}"><dt>${label}</dt><dd>${money(value)}</dd>${extra?`<small>${extra}</small>`:''}</div>`;
 return `<div class="finance-page"><header class="finance-heading"><div><div class="eyebrow">${club?'CAIXA DO CLUBE':'RESULTADO DA FAMÍLIA'}</div><h1>${club?'Financeiro do clube':'Financeiro da família'}</h1></div><div class="finance-header-actions">${btn('Exportar CSV','finance-export','secondary')}${btn(club?'Novo lançamento':'Lançar venda ou despesa','finance-new')}</div></header><section class="finance-dashboard" aria-label="Resumo financeiro do período"><form id="finance-filter" class="finance-period"><span class="finance-period-title">Visão do período</span><label><span class="sr-only">Período rápido</span><select name="preset" aria-label="Período rápido">${options([['custom','Personalizado'],['month','Este mês'],['previous','Mês anterior'],['year','Este ano']],v.preset||'custom')}</select></label><label>De<input name="from" type="date" value="${f.from}" required></label><label>Até<input name="to" type="date" value="${f.to}" required></label><button class="btn secondary" type="submit">Aplicar período</button></form><dl class="finance-metrics ${club?'':'family'}">${metric(club?'Saldo em caixa':'Saldo da família',t.closing,'closing','Anterior '+money(t.opening),'balance')}${metric(club?'Receitas operacionais':'Receitas de vendas',t.income,'income','Recebidas no período','income')}${club?metric('Aportes / investimentos',t.investments,'investments','Capital recebido'):''}${metric('Despesas pagas',t.expenses,'expenses','Pagamentos no período','expense')}${metric(club?'Resultado de caixa':'Entradas − saídas',t.result,'result','Receitas − despesas',t.result<0?'expense':'income')}</dl>${major.length?`<div class="finance-expense-breakdown"><span>Principais despesas</span>${major.map(([category,total])=>`<button type="button" data-action="finance-category" data-category="${esc(category)}" title="Filtrar ${esc(financeCategories[category]||category)}"><span>${esc(financeCategories[category]||category)}</span><b>${money(total)}</b><small>${Math.round(total/Math.max(1,t.expenses)*100)}%</small></button>`).join('')}</div>`:''}</section>${!club?financeLearningHtml():''}<section class="finance-ledger" aria-labelledby="finance-ledger-title"><div class="finance-ledger-heading"><div><h2 id="finance-ledger-title">Lançamentos</h2><p>Filtre e classifique os registros do período. O resumo acima permanece completo.</p></div>${club?`<div class="finance-quick-actions">${btn('Recebimento de família','finance-receive','secondary small')}${btn('Comprar filamento','stock-buy','secondary small')}${btn('Ver estoque','open-stock','secondary small')}</div>`:''}</div><div class="finance-list-filters" role="group" aria-label="Filtros dos lançamentos"><label class="finance-search">Buscar<input type="search" data-finance-filter="search" value="${esc(v.search)}" placeholder="Descrição, família ou categoria" autocomplete="off"></label><label>Tipo<select data-finance-filter="kind">${options([['all','Todos os tipos'],['income','Receitas'],['expense','Despesas'],...(club?[['investment','Aportes']]:[])],v.kind)}</select></label><label>Categoria<select data-finance-filter="category">${options([['all','Todas as categorias'],...categories.map(c=>[c,financeCategories[c]||c])],v.category)}</select></label>${!club?`<label>Participante<select data-finance-filter="participant">${options([['all','Toda a família'],['family','Família (compartilhado)'],...(f.people||[]).map(p=>[p.key,p.name])],v.participant)}</select></label>`:''}<label>Situação<select data-finance-filter="status">${options([['active','Confirmados'],['all','Todas as situações'],['voided','Estornados']],v.status)}</select></label><label>Ordenar por<select data-finance-filter="sort">${options([['date_desc','Mais recentes'],['date_asc','Mais antigos'],['value_desc','Maior valor'],['value_asc','Menor valor'],['description','Descrição A–Z']],v.sort)}</select></label>${btn('Limpar','finance-clear','secondary small')}</div><div id="finance-list">${financeTableHtml()}</div></section>${!club?'<p class="finance-footnote">Este financeiro é compartilhado pela família. Filtre por participante para acompanhar as escolhas de cada pessoa. Pagamentos ao clube são identificados como Família. Saldo não é lucro: considere os custos de cada venda.</p>':''}</div>`;
}
function stockPage(){const s=state.stock;return `${header('MATERIAL PARA CRIAR','Estoque de filamentos','Compras por lote, saldo em gramas e registro das baixas.',s.canBuy?btn('Registrar compra','stock-buy'):'')}<div class="grid two"><div class="card"><small>Filamento disponível</small><h2>${(s.totals.grams/1000).toLocaleString('pt-BR')} kg</h2></div>${s.canBuy?`<div class="card"><small>Valor do estoque a custo de compra</small><h2>${money(s.totals.value)}</h2></div>`:''}</div><div class="notice section"><p>Cada compra gera uma despesa no caixa. A baixa registra o filamento utilizado, perdido ou destinado a um projeto; não gera uma segunda despesa. Ao concluir uma impressão, registre aqui a baixa do lote utilizado.</p></div><div class="grid two section">${s.lots.map(l=>`<article class="card"><h2>${esc(l.material)} · ${esc(l.color)}</h2><p>Lote #${l.id} · ${esc(l.supplier||'Fornecedor não informado')} · ${esc(l.entry_date)}</p><div class="summary"><div><span>Comprado</span><strong>${l.grams} g</strong></div><div><span>Baixas</span><strong>${l.used_grams} g</strong></div><div><span>Saldo</span><strong>${l.remaining} g</strong></div>${s.canBuy?`<div><span>Valor pago / custo por kg</span><strong>${money(l.cents)} / ${money(l.costPerKg)}</strong></div><div><span>Valor restante</span><strong>${money(l.remainingValue)}</strong></div>`:''}</div>${l.remaining?btn('Registrar baixa','stock-use','secondary section',`data-id="${l.id}" data-max="${l.remaining}"`):''}</article>`).join('')||'<div class="card"><p>Nenhum filamento cadastrado. Registre a compra inicial com a data e o valor efetivamente pagos.</p></div>'}</div><details class="card section"><summary>Últimas baixas de estoque</summary>${s.uses.map(x=>`<p><strong>Lote #${x.lot_id}: ${x.grams} g</strong> · ${esc(x.reason)}<br><small>${esc(x.author)} · ${date(x.created)}</small></p>`).join('')||'<p>Nenhuma baixa registrada.</p>'}</details>`;}
async function paymentEditor(fid,initial={}){
 const f=state.data.families.find(f=>f.id===Number(fid)),benefits=(await api('/benefits?familyId='+fid)).benefits.filter(b=>b.kind==='discount'&&b.status==='available');
 const gross=initial.gross??(f?.plan==='annual'?state.data.config.annual:state.data.config.monthly);
 state.paymentDraft={familyId:Number(fid),requestKey:initial.requestKey||crypto.randomUUID(),...initial};
 modal('Registrar pagamento da participação',`<form id="payment-preview-form" class="stack"><p>${esc(f?.name||'Família')} · ${f?.plan==='annual'?'Anuidade':'Mensalidade'}</p><label>Referência<input name="description" required maxlength="150" value="${esc(initial.description||'')}" placeholder="Mensalidade de novembro de 2026"></label><label>Data do recebimento<input name="entryDate" type="date" value="${initial.entryDate||todayLocal()}" max="${todayLocal()}" required></label><label>Valor original (R$)<input name="gross" type="number" min="0.01" max="100000" step="0.01" value="${gross/100}" required></label><label>Cupom<select name="coupon"><option value="">Sem cupom</option>${benefits.map(b=>`<option value="${esc(b.code)}" data-value="${b.value}" ${initial.coupon===b.code?'selected':''}>${esc(b.code)} · ${money(b.value)} · até ${b.expiresOn.split('-').reverse().join('/')}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="waiver" ${initial.waiver?'checked':''}>Conceder isenção total</label><label>Motivo da isenção (se selecionada)<input name="reason" maxlength="150" value="${esc(initial.reason||'')}"></label><div id="payment-live" class="summary" aria-live="polite"></div><small>Os custos de impressão são recebidos no próprio projeto. Confirme a seguir apenas valores já recebidos.</small><button class="btn" type="submit">Conferir recebimento</button></form>`);updatePaymentSummary();
}
function updatePaymentSummary(){const f=$('#payment-preview-form');if(!f)return;const gross=Math.round(Number(f.elements.gross.value)*100),discount=f.elements.waiver.checked?gross:Math.min(gross,Number(f.elements.coupon.selectedOptions[0]?.dataset.value||0));f.elements.coupon.disabled=f.elements.waiver.checked;f.elements.reason.required=f.elements.waiver.checked;$('#payment-live').innerHTML=`<div><span>Valor original</span><strong>${money(gross)}</strong></div><div><span>Desconto</span><strong>${money(discount)}</strong></div><div class="total"><span>Valor a receber</span><strong>${money(Math.max(0,gross-discount))}</strong></div>`;}
function cashCategoryOptions(scope,kind){const choices=scope==='club'?{investment:['capital'],income:['other_income'],expense:['equipment','maintenance','rent','energy','services','other_expense']}:{income:['sales','allowance','gift','other_income'],expense:['supplies','shipping','purchase','other_expense']};return choices[kind].map(v=>`<option value="${v}">${financeCategories[v]}</option>`).join('');}
async function operationAction(action,target){if(await billingAction(action,target))return true;if(await paAction(action,target))return true;switch(action){
 case'finance-clear':state.financeView[state.finance.scope]={search:'',kind:'all',category:'all',participant:'all',status:'active',sort:'date_desc',page:1};render();return true;
 case'finance-page':financeView().page=Number(target.dataset.page);updateFinanceList();return true;
 case'finance-category':Object.assign(financeView(),{kind:'expense',category:target.dataset.category,page:1});render();return true;

 case'open-stock':state.page='stock';await refresh();return true;
 case'open-finance-club':state.page='finance-club';await refresh({navigate:true});return true;
 case'open-billing':state.page='billing';await refresh({navigate:true});return true;
 case'finance-new':{const scope=state.finance.scope;modal(scope==='club'?'Lançar movimentação do clube':'Lançar venda ou despesa',`<form id="cash-form" data-scope="${scope}" data-key="${crypto.randomUUID()}" class="stack"><label>Tipo<select name="kind"><option value="income">${scope==='club'?'Outra receita':'Receita de venda'}</option><option value="expense">Despesa</option>${scope==='club'?'<option value="investment">Aporte / investimento inicial</option>':''}</select></label><label>Categoria<select name="category">${cashCategoryOptions(scope,'income')}</select></label>${scope==='family'?familyParticipantField():''}<label>Descrição<input name="description" required maxlength="200" placeholder="${scope==='club'?'Ex.: aporte para iniciar o clube':'Ex.: venda de 3 chaveiros'}"></label><label>Valor recebido ou pago (R$)<input name="amount" type="number" min="0.01" max="1000000" step="0.01" required></label><label>Data<input name="entryDate" type="date" value="${todayLocal()}" max="${todayLocal()}" required></label><small>${scope==='club'?'Recebimentos de participantes são registrados na família ou no projeto. Compras de filamento são registradas em Estoque.':'Pagamentos ao clube já aparecem automaticamente. Registre apenas dinheiro que entrou ou saiu da família. Repasses entre membros não são nova receita.'}</small><button type="submit" class="btn">Salvar lançamento</button></form>`);return true;}
 case'finance-receive':modal('Escolha a família',`<div class="stack">${state.data.families.map(f=>btn(esc(f.name),'payment-dialog','secondary',`data-id="${f.id}"`)).join('')||'<p>Cadastre uma família primeiro.</p>'}</div>`);return true;
 case'payment-dialog':await paymentEditor(target.dataset.id);return true;
 case'payment-back':await paymentEditor(state.paymentDraft.familyId,state.paymentDraft);return true;
 case'finance-void':modal('Estornar lançamento',`<form id="void-form" data-id="${target.dataset.id}" class="stack"><p>O registro continuará no histórico com o motivo do estorno. O valor deixará de compor os totais.</p><label>Motivo<input name="reason" required maxlength="200"></label><button class="btn" type="submit">Confirmar estorno</button></form>`);return true;
 case'finance-export':{const f=state.finance;downloadCsv('financeiro-'+f.scope+'-'+f.from+'-'+f.to+'.csv',[['Data','Tipo','Categoria','Descrição','Valor (R$)','Participante','Situação','Motivo do estorno'],...financeVisibleEntries().map(e=>[e.entry_date,({income:'Receita',expense:'Despesa',investment:'Aporte'})[e.kind],financeCategories[e.category],e.description,(e.cents/100).toFixed(2),e.participant_name||'',e.voided_at?'Estornado':'Confirmado',e.void_reason||''])]);return true;}
 case'stock-buy':modal('Registrar compra de filamento',`<form id="stock-buy-form" data-key="${crypto.randomUUID()}" class="stack"><label>Material<input name="material" maxlength="60" required placeholder="PLA"></label><label>Cor<input name="color" maxlength="60" required></label><label>Fornecedor (opcional)<input name="supplier" maxlength="100"></label><label>Peso total adquirido (g)<input name="grams" type="number" min="1" max="1000000" step="1" required placeholder="1000"></label><label>Valor total pago (R$, incluindo frete)<input name="amount" type="number" min="0" max="1000000" step="0.01" required></label><label>Data da compra<input name="entryDate" type="date" value="${todayLocal()}" max="${todayLocal()}" required></label><p>Esta compra registra a despesa e a entrada no estoque em uma única operação.</p><button type="submit" class="btn">Registrar compra e entrada</button></form>`);return true;
 case'stock-use':modal('Registrar baixa de filamento',`<form id="stock-use-form" data-id="${target.dataset.id}" data-key="${crypto.randomUUID()}" class="stack"><p>Lote #${target.dataset.id} · disponível ${target.dataset.max} g</p><label>Quantidade consumida ou perdida (g)<input name="grams" type="number" min="1" max="${target.dataset.max}" step="1" required></label><label>Motivo ou projeto<input name="reason" required maxlength="200" placeholder="Ex.: projeto #15, incluindo suportes"></label><button class="btn" type="submit">Registrar baixa</button></form>`);return true;
 case'benefit-dialog':modal('Dar cupom ou horas',`<form id="benefit-form-v4" data-id="${target.dataset.id}" class="stack"><label>Benefício<select name="kind"><option value="hours">Horas de uso gratuitas</option><option value="discount">Cupom de desconto em R$</option></select></label><label><span data-benefit="valueLabel">Quantas horas de crédito?</span><input name="value" type="number" min="0.01" max="1000" step="0.01" required></label><small class="field-help" data-benefit="valueHelp">Exemplo: 2,5 = duas horas e meia de impressão.</small><label data-benefit="codeRow" hidden>Nome do cupom<input name="code" maxlength="40" pattern="[A-Za-z0-9_-]+" placeholder="Ex.: BEMVINDO10"></label><small class="field-help" data-benefit="codeHelp" hidden>É só um nome para você identificar o cupom, sem espaços nem acentos. Ele aparece na lista de cupons ao registrar o pagamento desta família, e não pode se repetir.</small>${dateField('Válido até','expiresOn',defaultExpiry())}<label>Motivo<input name="reason" required maxlength="150" placeholder="Ex.: presente de fim de ano"></label><label class="check" data-benefit="notifyRow"><input type="checkbox" name="notify" checked>Avisar a família no WhatsApp</label><p data-benefit="note">Horas são concedidas uma única vez, com validade própria, e somam ao saldo da família para novas aprovações.</p><button class="btn" type="submit">Conceder benefício</button></form>`);return true;
 case'hours-bulk':modal('Dar horas a várias famílias',`<form id="hours-bulk-form" class="stack"><fieldset class="stack"><legend>Famílias</legend><label class="check"><input type="checkbox" id="hours-all">Marcar todas</label>${state.data.families.map(f=>`<label class="check"><input type="checkbox" name="fam" value="${f.id}">${esc(f.name)}</label>`).join('')}</fieldset><label>Horas para cada família<input name="value" type="number" min="0.01" max="1000" step="0.01" required></label>${dateField('Válido até','expiresOn',defaultExpiry())}<label>Motivo<input name="reason" required maxlength="150" placeholder="Ex.: presente de fim de ano"></label><label class="check"><input type="checkbox" name="notify" checked>Avisar cada família no WhatsApp</label><p>Cada família recebe uma concessão própria, única e com validade, que aparece no histórico dela.</p><button class="btn" type="submit">Conceder horas</button></form>`);return true;
 case'benefits-history':{const r=await api('/benefits?familyId='+target.dataset.id);modal('Histórico de benefícios',`<div class="stack">${r.benefits.map(b=>`<article class="card"><div class="row spread"><h3>${b.kind==='hours'?hours(b.value)+' de bônus':esc(b.code)+' · '+money(b.value)}</h3><span class="badge">${({available:'Disponível',used:'Utilizado',expired:'Vencido',exhausted:'Saldo comprometido'})[b.status]}</span></div><p>${esc(b.reason)}</p><p>Concedido por ${esc(b.granted_by)} em ${date(b.created)}<br>Válido até ${b.expiresOn.split('-').reverse().join('/')}</p>${b.kind==='hours'?`<p>Usadas: ${hours(b.usedMinutes)} · Reservadas: ${hours(b.heldMinutes)} · ${b.status==='expired'?'Saldo vencido':'Saldo restante'}: ${hours(b.remaining)}</p>`:b.used?`<p>Utilizado ${b.redeemed_at?'em '+date(b.redeemed_at):'no pagamento da participação'}.</p>`:''}</article>`).join('')||'<p>Nenhum benefício concedido.</p>'}</div>`);return true;}
 case'team-toggle':case'team-role':{const enabled=action==='team-role'||target.dataset.enabled==='true';modal(enabled?'Definir acesso à equipe':'Remover acesso à equipe',`<form id="team-role-form" data-id="${target.dataset.id}" data-enabled="${enabled}" class="stack">${enabled?`<label>Função<select name="accessRole">${roleOptions(target.dataset.role)}</select></label>`:'<p>A conta manterá seu vínculo com a família. Colaboradores sem família perderão o acesso ao portal.</p>'}<label class="check"><input type="checkbox" required>Conferi a alteração de acesso. A pessoa precisará entrar novamente.</label><button type="submit" class="btn">Confirmar alteração</button></form>`);return true;}
 case'staff-invite':modal('Convidar colaborador',`<form id="staff-invite-form" class="stack"><label>E-mail do colaborador<input name="email" type="email" required maxlength="150"></label><label>Função<select name="accessRole">${roleOptions()}</select></label><p>O convite vale por 7 dias e permite criar uma conta de adulto sem vincular uma família. Você compartilhará o link com o colaborador.</p><button type="submit" class="btn">Gerar convite</button></form>`);return true;
 case'staff-revoke':await api('/staff-invites/revoke',{id:target.dataset.id});await refresh();toast('Convite revogado.');return true;
 default:return false;
}}
function downloadCsv(filename,rows){const csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(';')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function operationSubmit(form){if(await billingSubmit(form))return true;const fd=new FormData(form),o=Object.fromEntries(fd);switch(form.id){
 case'finance-filter':{const scope=state.finance.scope;state.financeRange??={};state.financeRange[scope]={from:o.from,to:o.to};financeView().page=1;financeView().preset=o.preset;await loadOperationsPage();render();return true;}
 case'cash-form':await api('/finance/entries',{scope:form.dataset.scope,requestKey:form.dataset.key,kind:o.kind,category:o.category,description:o.description,participantKey:o.participantKey,cents:Math.round(Number(o.amount)*100),entryDate:o.entryDate});break;
 case'void-form':await api(`/finance/entries/${form.dataset.id}/void`,{reason:o.reason});break;
 case'stock-buy-form':await api('/stock/purchases',{...o,requestKey:form.dataset.key,cents:Math.round(Number(o.amount)*100),grams:Number(o.grams)});break;
 case'stock-use-form':await api('/stock/use',{lotId:Number(form.dataset.id),grams:Number(o.grams),reason:o.reason,requestKey:form.dataset.key});break;
 case'benefit-form-v4':await api('/benefits',{familyId:Number(form.dataset.id),kind:o.kind,value:Math.round(Number(o.value)*(o.kind==='hours'?60:100)),code:o.code,expiresOn:dateIso(o.expiresOn),reason:o.reason,notify:fd.has('notify')});break;
 case'hours-bulk-form':{const ids=[...form.querySelectorAll('[name=fam]:checked')].map(c=>Number(c.value));if(!ids.length)throw new Error('Marque pelo menos uma família.');await api('/benefits',{familyIds:ids,kind:'hours',value:Math.round(Number(o.value)*60),expiresOn:dateIso(o.expiresOn),reason:o.reason,notify:fd.has('notify')});close();await refresh();toast(`Horas concedidas a ${ids.length} ${ids.length>1?'famílias':'família'}.`);return true;}
 case'team-role-form':await api('/team/'+form.dataset.id,{enabled:form.dataset.enabled==='true',accessRole:o.accessRole});break;
 case'staff-invite-form':{const r=await api('/staff-invites',o);modal('Convite de colaborador pronto',`<p>Compartilhe este link com ${esc(o.email)}. A função será ${accessLabels[o.accessRole]}.</p><label>Link de convite<input id="invite-link" readonly value="${esc(location.origin+'/?equipe='+r.token)}"></label>${btn('Copiar convite','copy-invite')}<p>Válido até ${date(r.expires)}. Guarde o link: ele só aparece agora.</p>`);return true;}
 case'staff-register-form':await api('/staff-register',{...o,token:new URLSearchParams(location.search).get('equipe')});history.replaceState(null,'','/');await boot();return true;
 case'payment-preview-form':{
  state.paymentDraft={...state.paymentDraft,...o,gross:Math.round(Number(o.gross)*100),waiver:fd.has('waiver'),coupon:fd.has('waiver')?'':o.coupon};
  const q=await api('/payments/preview',state.paymentDraft);state.paymentDraft.cents=q.total;
  modal('Conferir recebimento',`<form id="payment-confirm-form" class="stack"><p>${esc(o.description)} · ${esc(o.entryDate.split('-').reverse().join('/'))}</p><div class="summary"><div><span>Valor original</span><strong>${money(q.gross)}</strong></div><div><span>Desconto / isenção</span><strong>${money(q.discount)}</strong></div><div class="total"><span>${q.total?'Valor efetivamente recebido':'Isenção total'}</span><strong>${money(q.total)}</strong></div></div>${state.paymentDraft.waiver?`<p>Motivo: ${esc(o.reason)}</p>`:''}<label class="check"><input type="checkbox" required>${q.total?'Confirmo que este valor já foi recebido.':'Confirmo a isenção total desta participação.'}</label><button type="submit" class="btn">Confirmar registro</button>${btn('Voltar e ajustar','payment-back','secondary')}</form>`);return true;
 }
 case'payment-confirm-form':await api('/payments',state.paymentDraft);state.paymentDraft=null;break;
 default:return false;
}close();await refresh();toast('Registro salvo.');return true;}
async function renderStaffRegistration(token){try{const i=await api('/staff-invite?token='+encodeURIComponent(token));$('#app').innerHTML=`<main class="auth-layout"><section class="auth-story">${brand}<h1>Faça parte da equipe.</h1><p>Seu acesso será: ${accessLabels[i.access_role]}.</p></section><section class="auth-card"><h2>Criar conta de colaborador</h2><form id="staff-register-form" class="stack auth-form"><label>Seu nome<input name="name" required maxlength="80" autocomplete="name"></label><label>E-mail<input name="email" type="email" value="${esc(i.email)}" readonly required autocomplete="email"></label><label>Senha<input name="password" type="password" minlength="6" maxlength="200" autocomplete="new-password" required></label><label class="check"><input type="checkbox" required>Sou adulto e estou autorizado a atuar nesta função.</label><div class="error" role="alert"></div><button class="btn" type="submit">Criar minha conta</button></form></section></main>`;}catch(e){$('#app').innerHTML=`<main class="empty"><h1>Convite indisponível</h1><p>${esc(e.message)}</p><a href="/">Voltar para o portal</a></main>`;}}
document.addEventListener('input',e=>{if(e.target.closest('#payment-preview-form'))updatePaymentSummary();});
document.addEventListener('change',e=>{if(e.target.closest('#payment-preview-form'))updatePaymentSummary();if(e.target.matches('#benefit-form-v4 [name=kind]'))benefitKindChanged(e.target.form);
if(e.target.matches('#cash-form [name=kind]')){const f=e.target.form;f.elements.category.innerHTML=cashCategoryOptions(f.dataset.scope,e.target.value);}});

document.addEventListener('input',e=>{if(e.target.matches('[data-finance-filter="search"]')){financeView().search=e.target.value;financeView().page=1;updateFinanceList();}});
document.addEventListener('change',async e=>{
 if(e.target.matches('select[data-finance-filter]')){financeView()[e.target.dataset.financeFilter]=e.target.value;financeView().page=1;updateFinanceList();}
 if(e.target.matches('#finance-filter [name=preset]')){
  const form=e.target.form,now=todayLocal(),[y,m]=now.split('-').map(Number);let from,to;
  if(e.target.value==='month'){from=now.slice(0,7)+'-01';to=defaultExpiry();}
  if(e.target.value==='year'){from=y+'-01-01';to=y+'-12-31';}
  if(e.target.value==='previous'){const d=new Date(Date.UTC(y,m-2,1)),year=d.getUTCFullYear(),month=d.getUTCMonth()+1;from=year+'-'+String(month).padStart(2,'0')+'-01';to=year+'-'+String(month).padStart(2,'0')+'-'+new Date(Date.UTC(year,month,0)).getUTCDate();}
  if(from){form.elements.from.value=from;form.elements.to.value=to;form.requestSubmit();}
 }
 if(e.target.matches('#finance-filter input[type=date]'))e.target.form.elements.preset.value='custom';
});

function familyParticipantField(){const f=state.finance,role={guardian:'responsável',learner:'aprendiz',participant:'participante'};return f.guardian?`<label>Participante deste lançamento<select name="participantKey"><option value="family">Família (compartilhado)</option>${f.people.map(p=>`<option value="${p.key}" ${p.key===f.actorKey?'selected':''}>${esc(p.name)} · ${role[p.role]}</option>`).join('')}</select></label>`:`<p>Participante: <strong>${esc(f.people.find(p=>p.key===f.actorKey)?.name||state.user.name)}</strong>. O seu responsável pode acompanhar os registros.</p>`;}
function financeLearningHtml(){return `<details class="finance-learning"><summary>Aprender em família: receita, despesa, saldo e lucro</summary><div class="finance-concepts"><p><b>Receita é o que entra.</b> Uma venda ou dinheiro recebido de fora da família aumenta o saldo. Repassar dinheiro entre membros não cria uma nova receita da família.</p><p><b>Despesa é o que sai.</b> Material, embalagem e compras diminuem o saldo.</p><p><b>Saldo é o que temos.</b> Saldo anterior + entradas − saídas = saldo de agora.</p><p><b>Lucro é o que sobra de uma venda.</b> Valor vendido − custo para produzir e entregar. Mesada e aporte não são lucro de vendas.</p></div><h3>Vamos calcular uma venda?</h3><p>Experimente os números. Esta calculadora não cria lançamentos reais.</p><div class="finance-calculator"><label>Quantidade de peças<input id="learn-quantity" type="number" min="1" max="1000" step="1" value="1"></label><label>Preço de cada peça (R$)<input id="learn-price" type="number" min="0" max="10000" step="0.01" value="10"></label><label>Custo de cada peça (R$)<input id="learn-cost" type="number" min="0" max="10000" step="0.01" value="4"></label></div><output id="learn-result" aria-live="polite">R$ 10,00 de venda − R$ 4,00 de custo = R$ 6,00 de lucro estimado.</output><small>Inclua material, embalagem e entrega nos custos. A estimativa considera apenas os valores informados.</small></details>`;}
document.addEventListener('input',e=>{if(!e.target.closest('.finance-calculator'))return;const q=Math.max(1,Math.min(1000,Math.floor(Number($('#learn-quantity').value)||1))),p=Math.max(0,Math.min(1000000,Math.round(Number($('#learn-price').value)*100)||0)),c=Math.max(0,Math.min(1000000,Math.round(Number($('#learn-cost').value)*100)||0)),sales=q*p,cost=q*c,profit=sales-cost;$('#learn-result').textContent=`${q} × ${money(p)} = ${money(sales)} em vendas. ${q} × ${money(c)} = ${money(cost)} de custo. ${profit<0?'Prejuízo':'Lucro'} estimado: ${money(profit)}.${sales?' Margem sobre a venda: '+(profit/sales*100).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%.':''}`;});
// Club dashboard: six months of cash entries, open charges and filament stock, summarised in the browser.
const monthLabel=key=>new Date(key+'-15T12:00:00Z').toLocaleDateString('pt-BR',{month:'short',timeZone:'UTC'}).replace('.','');
async function loadFinanceDashboard(){const today=todayLocal(),[y,m]=today.split('-').map(Number),from=new Date(Date.UTC(y,m-6,1)).toISOString().slice(0,10),to=defaultExpiry(),months=[...Array(6)].map((_,i)=>new Date(Date.UTC(y,m-6+i,1)).toISOString().slice(0,7));
 const [finance,billing,stock]=await Promise.all([api('/finance?'+new URLSearchParams({scope:'club',from,to})),api('/billing').catch(()=>null),api('/stock').catch(()=>null)]);state.financeDashboard={finance,billing,stock,months};}
function financeDashboardPage(){const {finance,billing,stock,months}=state.financeDashboard,live=finance.entries.filter(e=>!e.voided_at);
 const byMonth=months.map(k=>{const rows=live.filter(e=>e.entry_date.startsWith(k)),sum=kind=>rows.filter(e=>e.kind===kind).reduce((n,e)=>n+e.cents,0);return {key:k,income:sum('income'),expense:sum('expense'),investment:sum('investment')};});
 const now=byMonth[5],before=byMonth[4],result=now.income-now.expense,delta=(a,b,good=1)=>{if(!b)return '';const d=Math.round((a-b)/b*100);return `<small class="${d*good>=0?'up':'down'}">${d>=0?'▲':'▼'} ${Math.abs(d)}% vs. ${monthLabel(before.key)}</small>`;};
 const top=Math.max(1,...byMonth.flatMap(r=>[r.income,r.expense])),h=150,bw=22;
 const chart=`<svg class="fin-chart" viewBox="0 0 600 200" role="img" aria-label="Receitas e despesas dos últimos seis meses">${[0,.5,1].map(f=>`<line class="grid" x1="40" x2="590" y1="${20+h-f*h}" y2="${20+h-f*h}"/><text class="axis" x="34" y="${24+h-f*h}" text-anchor="end">${f?Math.round(top*f/100).toLocaleString('pt-BR'):'0'}</text>`).join('')}${byMonth.map((r,i)=>{const x=70+i*88,hi=r.income/top*h,he=r.expense/top*h;return `<g><title>${monthLabel(r.key)}: receitas ${money(r.income)}, despesas ${money(r.expense)}</title><rect class="inc" x="${x}" y="${20+h-hi}" width="${bw}" height="${hi}" rx="4"/><rect class="exp" x="${x+bw+4}" y="${20+h-he}" width="${bw}" height="${he}" rx="4"/><text class="axis" x="${x+bw+2}" y="192" text-anchor="middle">${monthLabel(r.key)}</text></g>`;}).join('')}</svg>`;
 const costs=new Map();for(const e of live)if(e.kind==='expense')costs.set(e.category,(costs.get(e.category)||0)+e.cents);const costList=[...costs].sort((a,b)=>b[1]-a[1]).slice(0,5),costTop=Math.max(1,...costList.map(c=>c[1]));
 const charges=billing?.charges||[],open=charges.filter(c=>['pending','past_due'].includes(c.status)),late=charges.filter(c=>c.status==='past_due'),sumC=list=>list.reduce((n,c)=>n+c.amountCents,0);
 const card=(label,value,extra='',tone='')=>`<div class="card fin-kpi ${tone}"><span>${label}</span><strong>${value}</strong>${extra}</div>`;
 return `${header('VISÃO DO CAIXA','Painel financeiro',`Resumo de ${monthLabel(now.key)} e dos últimos seis meses.`,`<div class="row">${btn('Ver lançamentos','open-finance-club','secondary')}${btn('Cobranças','open-billing','secondary')}</div>`)}<div class="fin-kpis">${card('Saldo em caixa',money(finance.totals.closing),'<small>Todas as movimentações até hoje</small>','balance')}${card('Receitas do mês',money(now.income),delta(now.income,before.income),'income')}${card('Despesas do mês',money(now.expense),delta(now.expense,before.expense,-1),'expense')}${card('Resultado do mês',money(result),'<small>Receitas − despesas</small>',result<0?'expense':'income')}${card('A receber',money(sumC(open)),`<small>${open.length} cobrança${open.length===1?'':'s'} em aberto${late.length?`, <b>${late.length} em atraso</b>`:''}</small>`,late.length?'expense':'')}</div><div class="grid two section"><section class="card"><div class="section-head"><h2>Receitas e despesas</h2><div class="fin-legend"><span class="inc">Receitas</span><span class="exp">Despesas</span></div></div>${chart}<table class="fin-months"><thead><tr><th>Mês</th><th>Receitas</th><th>Despesas</th><th>Resultado</th></tr></thead><tbody>${byMonth.slice().reverse().map(r=>`<tr><td>${monthLabel(r.key)}</td><td>${money(r.income)}</td><td>${money(r.expense)}</td><td class="${r.income-r.expense<0?'neg':''}">${money(r.income-r.expense)}</td></tr>`).join('')}</tbody></table></section><div class="stack"><section class="card"><h2>Para onde vai o dinheiro</h2><p class="muted">Maiores despesas dos últimos seis meses.</p>${costList.length?`<ul class="fin-bars">${costList.map(([c,v])=>`<li><div class="row spread"><span>${esc(financeCategories[c]||c)}</span><b>${money(v)}</b></div><svg viewBox="0 0 100 6" preserveAspectRatio="none" aria-hidden="true"><rect class="track" width="100" height="6" rx="3"/><rect class="fill" width="${Math.max(2,v/costTop*100)}" height="6" rx="3"/></svg></li>`).join('')}</ul>`:'<p>Nenhuma despesa registrada no período.</p>'}</section><section class="card"><h2>Cobranças em aberto</h2>${open.length?`<ul class="fin-list">${open.slice(0,6).map(c=>`<li><span>${esc(c.familyName)}<small>${c.status==='past_due'?'Em atraso':'Aguardando pagamento'}</small></span><b class="${c.status==='past_due'?'neg':''}">${money(c.amountCents)}</b></li>`).join('')}</ul>`:'<p class="muted">Nenhuma cobrança aguardando pagamento.</p>'}</section>${stock?`<section class="card"><h2>Estoque de filamento</h2><div class="row spread"><span>${Number((stock.totals.grams/1000).toFixed(2)).toLocaleString('pt-BR')} kg disponíveis</span><b>${money(stock.totals.value||0)}</b></div><p class="muted">Valor pelo custo de compra de cada lote.</p></section>`:''}${byMonth.some(r=>r.investment)?`<section class="card"><h2>Aportes no período</h2><div class="row spread"><span>Capital recebido em seis meses</span><b>${money(byMonth.reduce((n,r)=>n+r.investment,0))}</b></div></section>`:''}</div></div>`;}

document.addEventListener('change',e=>{if(e.target.id==='hours-all')for(const c of e.target.form.querySelectorAll('[name=fam]'))c.checked=e.target.checked;});

// A pergunta muda conforme o benefício: horas de impressão ou valor do desconto em reais.
function benefitKindChanged(form){
 const hours=form.elements.kind.value==='hours',set=(k,t)=>{const el=form.querySelector(`[data-benefit=${k}]`);if(el)el.textContent=t;},show=(k,on)=>{const el=form.querySelector(`[data-benefit=${k}]`);if(el)el.hidden=!on;};
 set('valueLabel',hours?'Quantas horas de crédito?':'Valor do desconto em R$');
 set('valueHelp',hours?'Exemplo: 2,5 = duas horas e meia de impressão.':'Exemplo: 10 = R$ 10,00 de desconto no pagamento da família.');
 form.elements.value.max=hours?1000:100000;
 show('codeRow',!hours);show('codeHelp',!hours);show('notifyRow',hours);form.elements.code.required=!hours;
 set('note',hours?'Horas são concedidas uma única vez, com validade própria, e somam ao saldo da família para novas aprovações.':'O cupom é exclusivo desta família e de uso único, e abate o valor quando a equipe registrar o pagamento desta família.');
}
// Máscara dd/mm/aaaa enquanto digita.
document.addEventListener('input',e=>{if(!e.target.classList?.contains('date-br'))return;const d=e.target.value.replace(/\D/g,'').slice(0,8);e.target.value=[d.slice(0,2),d.slice(2,4),d.slice(4)].filter(Boolean).join('/');});

// ---- Pedidos da equipe: busca, filtros, ordem e ações em massa ----
const paOrder=['draft','review','question','approval','queued','printing','ready','completed','cancelled','failed'];
const paState=()=>state.pa??={q:'',status:'',family:'',sort:'updated',dir:'desc',sel:new Set()};
const paNorm=v=>String(v??'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();
const paNumber=p=>'#'+String(p.id).padStart(3,'0');
function paRows(){
 const f=paState(),q=paNorm(f.q).trim(),keys={updated:p=>p.updated,id:p=>p.id,name:p=>paNorm(p.name),family:p=>paNorm(p.family_name||p.participant),status:p=>paOrder.indexOf(p.status)},key=keys[f.sort]||keys.updated,dir=f.dir==='asc'?1:-1;
 return projectsBase().filter(p=>(!f.status||p.status===f.status)&&(!f.family||String(p.family_id)===f.family)&&(!q||paNorm(`${p.name} ${p.family_name||''} ${p.participant||''} ${paNumber(p)} ${p.id}`).includes(q))).sort((a,b)=>{const x=key(a),y=key(b);return ((x<y?-1:x>y?1:0)*dir)||(b.id-a.id);});
}
function adminProjectsPage(){
 const f=paState(),families=state.data.families||[];
 const sorts=[['updated','desc','Atualizados há menos tempo'],['updated','asc','Atualizados há mais tempo'],['id','desc','Número (maior primeiro)'],['id','asc','Número (menor primeiro)'],['name','asc','Nome (A–Z)'],['family','asc','Família (A–Z)'],['status','asc','Etapa']];
 return `<div class="pa-tools"><label class="pa-search">Buscar<input id="pa-q" type="search" placeholder="Nome, família, participante ou número" value="${esc(f.q)}" autocomplete="off"></label>
 <label>Etapa<select id="pa-status"><option value="">Todas</option>${paOrder.map(s=>`<option value="${s}" ${f.status===s?'selected':''}>${esc(labels[s])}</option>`).join('')}</select></label>
 <label>Família<select id="pa-family"><option value="">Todas</option>${families.map(x=>`<option value="${x.id}" ${f.family===String(x.id)?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>
 <label>Ordenar por<select id="pa-sort">${sorts.map(([k,d,l])=>`<option value="${k}:${d}" ${f.sort===k&&f.dir===d?'selected':''}>${l}</option>`).join('')}</select></label></div>
 <div id="pa-list">${paListHtml()}</div>`;
}
function paListHtml(){
 const f=paState(),rows=paRows(),visible=new Set(rows.map(p=>p.id));for(const id of [...f.sel])if(!visible.has(id))f.sel.delete(id);
 const arrow=k=>f.sort===k?(f.dir==='asc'?' ▲':' ▼'):'',th=(k,l)=>`<th><button type="button" class="text-btn pa-th" data-action="pa-sort" data-sort="${k}">${l}${arrow(k)}</button></th>`;
 const selected=rows.filter(p=>f.sel.has(p.id)),filtered=Boolean(f.q||f.status||f.family);
 const bulk=adminUser()?`<div class="pa-bulk ${selected.length?'on':''}" role="region" aria-label="Ações em massa"><strong>${selected.length?`${selected.length} selecionado${selected.length>1?'s':''}`:'Marque pedidos na lista para agir em vários de uma vez'}</strong>${selected.length?`<span class="row">${btn('Finalizar (já impressos)','pa-bulk','secondary small','data-do="finish"')}${btn('Cancelar','pa-bulk','secondary small','data-do="cancel"')}${btn('Excluir','pa-bulk','secondary small danger','data-do="delete"')}${btn('Limpar seleção','pa-sel-clear','secondary small')}</span>`:''}</div>`:'';
 const body=rows.length?`<div class="card table-wrap"><table class="pa-table"><thead><tr>${adminUser()?`<th class="pa-check-col"><input type="checkbox" id="pa-all" aria-label="Marcar todos os pedidos da lista" ${selected.length&&selected.length===rows.length?'checked':''}></th>`:''}${th('name','Projeto')}${th('family','Família / participante')}${th('status','Etapa')}${th('updated','Atualizado')}<th></th></tr></thead><tbody>${rows.map(p=>`<tr class="${f.sel.has(p.id)?'selected':''}">${adminUser()?`<td class="pa-check-col"><input type="checkbox" class="pa-check" data-id="${p.id}" aria-label="Marcar ${esc(p.name)}" ${f.sel.has(p.id)?'checked':''}></td>`:''}<td><div class="row-model">${p.model_site?modelThumb(Number(p.model_image)?`/api/model-image/${p.id}`:null):''}<div><strong>${esc(p.name)}</strong><br><small>${paNumber(p)}${p.model_site?' · '+esc(siteNames[p.model_site]||'Link externo'):''}</small>${p.model_site&&licensePending(p)&&!['completed','cancelled'].includes(p.status)?'<br><span class="license-chip warn">Licença a conferir</span>':''}</div></div></td><td>${esc(p.family_name||p.participant)}</td><td>${badge(p.status)}</td><td>${date(p.updated)}</td><td><button class="text-btn" data-project="${p.id}">Abrir ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:empty(filtered?'Nenhum pedido com esses filtros':'Nenhum projeto nesta lista',filtered?'Ajuste a busca ou limpe os filtros para ver mais pedidos.':'Quando uma ideia chegar por aqui, você poderá acompanhar cada etapa.',filtered?btn('Limpar filtros','pa-clear','secondary'):'');
 return `<p class="pa-count" aria-live="polite">${rows.length} de ${state.data.projects.length} pedido${state.data.projects.length>1?'s':''}${filtered?` · ${btn('Limpar filtros','pa-clear','secondary small')}`:''}</p>${bulk}${body}`;
}
const paRefresh=()=>{const el=$('#pa-list');if(el)el.innerHTML=paListHtml();};
const paText={
 finish:{title:'Finalizar pedidos já impressos',verb:'Finalizar',note:'Só vale para pedidos que estão na fila. Cada um vira "Pronto para retirar" com o tempo e o filamento orçados, a família é avisada no WhatsApp, o filamento sai do estoque e o PIX do valor segue as regras de cobrança. Se o consumo real foi outro, finalize pelo pedido, informando os valores.'},
 cancel:{title:'Cancelar pedidos',verb:'Cancelar pedidos',note:'Cancela sem cobrança e libera as horas reservadas. Pedidos já em impressão ou concluídos não são cancelados por aqui.'},
 delete:{title:'Excluir pedidos',verb:'Excluir definitivamente',note:'Apaga o pedido, as mensagens e os arquivos. Só pedidos que nunca foram impressos nem cobrados: os demais ficam no histórico. Não dá para desfazer.'}
};
async function paAction(action,target){
 const f=paState();
 switch(action){
  case'pa-sort':{const k=target.dataset.sort;if(f.sort===k)f.dir=f.dir==='asc'?'desc':'asc';else{f.sort=k;f.dir=k==='updated'||k==='id'?'desc':'asc';}render();return true;}
  case'pa-clear':f.q='';f.status='';f.family='';render();return true;
  case'pa-sel-clear':f.sel.clear();paRefresh();return true;
  case'pa-bulk':{
   const kind=target.dataset.do,t=paText[kind],picked=paRows().filter(p=>f.sel.has(p.id));
   modal(t.title,`<div class="stack"><p><strong>${picked.length} pedido${picked.length>1?'s':''}:</strong></p><ul class="pa-picked">${picked.slice(0,12).map(p=>`<li>${paNumber(p)} · ${esc(p.name)} <small>(${esc(labels[p.status])})</small></li>`).join('')}${picked.length>12?`<li>e mais ${picked.length-12}…</li>`:''}</ul><p>${t.note}</p>${btn(t.verb,'pa-confirm','',`data-do="${kind}"`)}</div>`);return true;
  }
  case'pa-confirm':{
   const kind=target.dataset.do,ids=[...f.sel];target.disabled=true;
   const r=await api('/projects/bulk',{action:kind,ids});
   for(const id of r.done)f.sel.delete(id);close();await refresh();
   const words={finish:'finalizado',cancel:'cancelado',delete:'excluído'},w=words[kind];
   if(r.skipped.length){const byId=new Map(state.data.projects.map(p=>[p.id,p]));modal('Resultado',`<div class="stack"><p>${r.done.length?`${r.done.length} pedido${r.done.length>1?'s':''} ${w}${r.done.length>1?'s':''}.`:'Nenhum pedido foi alterado.'} ${r.skipped.length} ${r.skipped.length>1?'ficaram':'ficou'} de fora:</p><ul class="pa-picked">${r.skipped.map(s=>`<li>#${String(s.id).padStart(3,'0')}${byId.get(s.id)?' · '+esc(byId.get(s.id).name):''}: ${esc(s.reason)}</li>`).join('')}</ul></div>`);}
   else toast(`${r.done.length} pedido${r.done.length>1?'s':''} ${w}${r.done.length>1?'s':''}.`);
   return true;
  }
 }
 return false;
}
document.addEventListener('input',e=>{if(e.target.id==='pa-q'){paState().q=e.target.value;paRefresh();}});
document.addEventListener('change',e=>{
 const t=e.target,f=paState();
 if(t.id==='pa-status'){f.status=t.value;paRefresh();}
 else if(t.id==='pa-family'){f.family=t.value;paRefresh();}
 else if(t.id==='pa-sort'){[f.sort,f.dir]=t.value.split(':');paRefresh();}
 else if(t.id==='pa-all'){for(const p of paRows())t.checked?f.sel.add(p.id):f.sel.delete(p.id);paRefresh();}
 else if(t.classList?.contains('pa-check')){const id=Number(t.dataset.id);t.checked?f.sel.add(id):f.sel.delete(id);paRefresh();}
});
